import utilsfrom datetime import datetimeimport streamlit as stfrom svc import svc_backend as backendst.set_page_config(layout='wide', page_title='Create Monitor', initial_sidebar_state='expanded')st.header("Create Monitor")import authuser_code = auth.ensure_logged_in(required_access_level='guest')# ===========================================================# STEP 01# ===========================================================st.subheader(":material/manufacturing: Monitor Configuration")monitor_mapping = {    'APIs': 'api',    'Website': 'website',    'TCP Port': 'tcp',    'Domain Expiry': 'domain',    'SSL Expiry': 'ssl',    'DNS Lookup': 'dns',    'Database Connection': 'database',    'Event & Jobs': 'event'}input_monitor_type = st.radio('Select Monitor Type', monitor_mapping.keys(), index=0, horizontal=True)monitor_type = monitor_mapping[input_monitor_type]if monitor_type == 'api':    sample = """curl --location 'https://watchtower.finanssure.com/api/v1' \    --header 'Authorization:Bearer XXXXX==' \    --header 'version: 1'    """    cc = st.columns(2)    _input_ = cc[0].text_area('Request cURL', value=sample, height=150)    monitor_body = utils.parse_curl_command(_input_)    _default_name_ = f"API - {monitor_body.get('URL') if _input_ else ''}"    cc[1].write('Parsed cURL')    if 'error' in monitor_body:        cc[1].warning(f"Error: {monitor_body['error']}")    else:        cc[1].code(f"Method:\t {monitor_body.get('method')} \nURL:\t {monitor_body.get('url')}  \nHeaders: {monitor_body.get('headers')}  \nParams:\t {monitor_body.get('params')}  \nBody:\t {monitor_body.get('body')}", language='bash')elif monitor_type == 'website':    sample = 'https://watchtower.finanssure.com'    _input_ = st.text_input('Website URL', value=sample, placeholder='Enter Website URL')    _default_name_ = f"Website - {_input_}"    monitor_body = {'host': _input_}elif monitor_type == 'domain':    sample = 'finanssure.com'    _input_ = st.text_input('Domain Name', value=sample, placeholder='Enter Domain Name')    _default_name_ = f"Domain Expiry - {_input_}"    monitor_body = {'host': _input_}elif monitor_type == 'tcp':    sample = '20.207.73.82:443'    _input_ = st.text_input('Server Host & Port', value=sample, placeholder='Enter Server Host & Port')    _default_name_ = f"TCP - {_input_.strip()}" if _input_ else ''    monitor_body = {'host': _input_}elif monitor_type == 'ssl':    sample = 'finanssure.com'    _input_ = st.text_input('Domain Name', value=sample, placeholder='Enter Domain Name')    _default_name_ = f"SSL Expiry - {_input_}"    monitor_body = {'host': _input_}elif monitor_type == 'dns':    sample = 'finanssure.com'    _input_ = st.text_input('Host Name', value=sample, placeholder='Enter Host Name')    cc = st.columns([1, 4])    _record_type_ = cc[0].selectbox('Record Type', ['A', 'CNAME', 'MX', 'TXT'], index=0)    _nameservers_ = cc[1].text_input('Name Servers (Optional)', value=None, placeholder='Enter Name Servers (comma separated)', help='Leave empty for default (1.1.1.1, 8.8.8.8)')    monitor_body = {'host': _input_, 'record_type': _record_type_, 'nameservers': [x.strip() for x in _nameservers_.split(',')] if _nameservers_ else None}    _default_name_ = f"DNS Lookup - {_input_}"elif monitor_type == 'database':    sample = 'postgresql://POSTGRES_USER:POSTGRES_PASSWORD@127.0.0.1:5432'    _input_ = st.text_input('Database Connection String', value=sample, placeholder='Enter Database Connection String')    monitor_body = utils.parse_db_connection_string(_input_)    _default_name_ = f"Database ({monitor_body.get('scheme')}) - {monitor_body.get('host')}" if _input_ else ''elif monitor_type == 'event':    sample = None    _input_ = st.radio('Select Event Type', ['Asynchronous', 'Periodic'], index=0, horizontal=True)    monitor_body = {'event_type': _input_.lower()}    _default_name_ = f"Event - {_input_}"else:    raise ValueError('Invalid Monitor Type')if st.button('Test Monitor'):    if monitor_type == 'event':        st.warning('Event Monitor does not support Test')    elif _input_ in [None, ''] or 'error' in monitor_body:        st.error('Invalid monitor configuration')    else:        result = backend.check_monitor(monitor_type, monitor_body)        st.write(result)# ===========================================================# STEP 02: Expectation# ===========================================================st.subheader(":material/experiment: Define Expectation")if monitor_type == 'api':    test_response = st.radio('Test Response Codes', ['Response Codes - Success', 'Response Codes - Failure'], index=0, horizontal=True)    all_response_codes = [200, 201, 202, 204, 301, 302, 304, 400, 401, 403, 404, 500, 502, 503, 504]    if test_response == 'Response Codes - Success':        is_allow_list = True        default_response_codes = [200, 201, 202, 204]    else:        is_allow_list = False        default_response_codes = [400, 401, 403, 404, 500, 502, 503, 504]    selected_response_codes = st.multiselect('Response Codes', all_response_codes, default=default_response_codes)    monitor_expectation = {        'is_allow_list': is_allow_list,        'response_codes': selected_response_codes    }else:    monitor_expectation = None    st.markdown(f'_Expectation will be auto-decided for this Monitor Type: {input_monitor_type}_')# ===========================================================# STEP 03# ===========================================================st.subheader(":material/schedule: Schedule & Save")alert_channels_df = backend.get_alert_channels(user_code=user_code)if not alert_channels_df.empty:    alert_channels_df['channel'] = '[' + alert_channels_df['channel_type'] + '] ' + alert_channels_df['channel_name']else:    alert_channels_df['channel'] = Nonecc = st.columns([3, 1])monitor_name = cc[0].text_input('Monitor Name', placeholder='Enter Monitor Name', value=_default_name_)monitor_group = cc[1].text_input('Monitor Group', placeholder='Enter Monitor Group (Optional)')# check resource costly monitors less frequentlyinterval_mapping = {    # monitor_type: [default_interval, default_interval_unit, allowed_interval_units]    'api': [5, 'minutes', ['seconds', 'minutes', 'hours', 'days', 'weeks']],    'website': [5, 'minutes', ['seconds', 'minutes', 'hours', 'days', 'weeks']],    'tcp': [5, 'minutes', ['seconds', 'minutes', 'hours', 'days', 'weeks']],    'domain': [1, 'weeks', ['days', 'weeks']],    'ssl': [1, 'weeks', ['days', 'weeks']],    'dns': [1, 'weeks', ['days', 'weeks']],    'database': [10, 'minutes', ['seconds', 'minutes', 'hours', 'days', 'weeks']],    'event': [1, 'days', ['seconds', 'minutes', 'hours', 'days', 'weeks']]}if monitor_type == 'event':    cc = st.columns([2, 3])    # check schedule interval    monitor_interval = cc[0].text_input('Run Schedule', placeholder='Enter Comma Separated Schedule in Cron Syntax (Optional)', help='Leave empty for default')    monitor_interval_unit = 'cron'    # associate alert channels    alerts = cc[1].multiselect('Alert Channels', alert_channels_df['channel'].tolist(), default=None)    selected_channels = alert_channels_df[alert_channels_df['channel'].isin(alerts)]['channel_id'].tolist() if alerts else None    cc = st.columns([1, 1, 3])    monitor_timeout = cc[0].number_input('Max Delay (seconds)', value=120)    monitor_expiry = cc[1].date_input('Monitor Expiry', value=None, format='YYYY-MM-DD', min_value=datetime.now())    monitor_tags = cc[2].text_input('Monitor Tags', placeholder='Comma Separated Tags (Optional)')else:    cc = st.columns([1, 1, 3])    # check schedule interval    monitor_interval = cc[0].number_input('Monitor Interval', value=interval_mapping[monitor_type][0])    monitor_interval_unit = cc[1].selectbox('Interval Unit', interval_mapping[monitor_type][2], index=interval_mapping[monitor_type][2].index(interval_mapping[monitor_type][1]))    # associate alert channels    alerts = cc[2].multiselect('Alert Channels', alert_channels_df['channel'].tolist(), default=None)    selected_channels = alert_channels_df[alert_channels_df['channel'].isin(alerts)]['channel_id'].tolist() if alerts else None    cc = st.columns([1, 1, 3])    monitor_timeout = cc[0].number_input('Request Timeout (seconds)', value=5)    monitor_expiry = cc[1].date_input('Monitor Expiry', value=None, format='YYYY-MM-DD', min_value=datetime.now())    monitor_tags = cc[2].text_input('Monitor Tags', placeholder='Comma Separated Tags (Optional)')if st.button('Create Monitor', type='primary'):    if user_code == 'guest':        st.warning('Login required to create monitor')    elif _input_ in [sample, None, '']:        st.warning('Can not submit the Sample OR Invalid Monitor Body')    else:        res = backend.create_monitor(monitor_type, monitor_group, monitor_name, monitor_body, monitor_timeout, monitor_interval, monitor_interval_unit, monitor_expiry, monitor_expectation, selected_channels, monitor_tags, user_code, st.session_state.get('org_code'))        st.json(res)